export async function logPageView(path: string) {
  // Simulate an analytics service call (e.g. Segment, Amplitude, your own API).
  // This runs after the response is sent, so slow networks won't block the page.
  await new Promise((resolve) => setTimeout(resolve, 100))
  console.log(`[analytics] page view: ${path}`)
}

