import { after } from 'next/server'
import { logPageView } from './analytics'

export default function Home() {
  const path = '/'

  after(() => {
    logPageView(path)
  })

  return (
    <main>
      <h1>Welcome</h1>
      <p>Thanks for visiting our site.</p>
    </main>
  )
}

